function maxProfitWithFee(prices: number[], fee: number): number {
  const n = prices.length;
  const best = new Array(n).fill(0);
  for (let j = 1; j < n; j++) {
    best[j] = best[j - 1];
    for (let i = 0; i < j; i++) {
      best[j] = Math.max(best[j], best[i] + prices[j] - prices[i] - fee);
    }
  }
  return best[n - 1];
}

