function maxProfitWithFee(prices: number[], fee: number): number {
  let cash = 0, hold = -prices[0];
  for (let i = 1; i < prices.length; i++) {
    const p = prices[i];
    const newCash = Math.max(cash, hold + p - fee);
    hold = Math.max(hold, cash - p);
    cash = newCash;
  }
  return cash;
}

